window.SOP.id = 'enclosure'; window.SOP.doneText = 'Unit ready to ship';
window.TRAINING = [window.SOP, {"id": "camera-build", "title": "How to Build a Static Camera", "doc": "SiteVue camera · Pi 5 + AI HAT+ + Camera Module 3", "doneText": "Camera assembled", "ppe": ["Anti-static wrist strap, clipped to ground", "Work on an ESD-safe mat", "Clean, dry hands (or nitrile gloves)"], "tools": [["Electronics", ["Raspberry Pi 5", "AI HAT+ (Hailo NPU)", "Camera Module 3", "40-pin GPIO stacking header", "CSI camera ribbon", "PCIe FFC ribbon"]], ["Enclosure", ["Base", "Lid with camera tower", "Tower rear cover", "Lens bezel ring", "Rubber feet ×4"]], ["Hardware", ["M2.5 brass standoffs ×4", "M2.5 screws ×4 (HAT)", "M2 screws ×4 (camera)", "Lid side screws ×4"]], ["Cooling", ["Thermal pad", "Aluminium heatsink"]], ["Tools", ["Small Phillips screwdriver", "Driver for the M2.5 standoffs"]]], "steps": [["Base", "Press in the four rubber feet", "Turn the base upside down and press a rubber foot into each corner recess until it sits flat.", null, null, null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Base", "Lower the Raspberry Pi 5 onto the base", "Hold the board by its edges and line its four mounting holes up with the bosses in the base.", ["CAUTION", "Wear the grounded wrist strap from here on. Static can kill the Pi, the AI HAT+ and the camera without any visible damage."], ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Base", "Fit the four brass standoffs", "Thread an M2.5 standoff through each Pi mounting hole into the boss below. Snug, not tight.", ["NOTE", "These standoffs also carry the AI HAT+, so get all four fully seated."], ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Ribbons & header", "Connect the camera ribbon", "Open the Pi’s CAM connector latch, push the camera flex fully in, square to the connector, then close the latch.", ["NOTE", "A crooked or half-seated ribbon is the most common cause of “no camera detected”."], ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Ribbons & header", "Press on the GPIO stacking header", "Seat the 40-pin stacking header straight onto the Pi’s GPIO pins and press evenly along its length.", ["CAUTION", "Don’t rock the header. Bent pins won’t line up with the HAT."], ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["AI HAT+", "Drop the AI HAT+ into place", "Line the Hailo NPU HAT up with the standoffs and the stacking header, then press it down evenly.", null, ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["AI HAT+", "Link the HAT to the PCIe port", "Connect the flat PCIe ribbon between the HAT and the Pi’s PCIe connector, opening and closing both latches.", ["NOTE", "Handle the ribbon by its edges and never crease it."], ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["AI HAT+", "Secure the HAT with four screws", "Drive an M2.5 screw into each standoff through the HAT corners.", ["CAUTION", "Snug only. Over-tightening can crack the board."], ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Cooling", "Apply the thermal pad", "Peel both protective films and lay the pad squarely on the NPU chip.", ["NOTE", "Any film left on the pad blocks the heat path, and the NPU will throttle."], ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Cooling", "Seat the heatsink", "Lower the aluminium heatsink straight onto the thermal pad and press down gently.", null, ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Camera tower", "Fit the lens bezel ring", "Press the bezel ring into the camera tower window from the front.", null, null, null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Camera tower", "Slide in Camera Module 3", "Feed the camera in from the back of the tower with the lens through the window.", ["NOTE", "Keep fingers off the lens. Leave its protective cap on until final assembly if it has one."], ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Camera tower", "Fix the camera with four screws", "Drive four M2 screws through the camera board into the tower bosses.", null, ["ESD strap"], null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Camera tower", "Snap on the tower rear cover", "Press the rear cover onto the camera tower until it clicks all the way round.", null, null, null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Close up", "Lower the lid over the stack", "Bring the lid with its camera tower down over the electronics, routing the camera ribbon through the tower slot.", ["CAUTION", "Check the ribbon isn’t pinched between the lid and the base before you close it."], null, null, "data:image/jpeg;base64,", "data:video/mp4;base64,"], ["Close up", "Lock the lid with four side screws", "Drive the four side screws to fix the lid to the base. Your camera is assembled.", null, null, null, "data:image/jpeg;base64,", "data:video/mp4;base64,"]]}];
